import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long num = sc.nextLong();
        long den = sc.nextLong();
        long max_iter = sc.nextLong();

        long numerator = 1;
        long denominator = 1;
        double ratio = (double) num / den;
        double min_difference = Double.MAX_VALUE;
        double epsilon = 1e-25;

        if (den <= denominator) {
            System.out.println(num + "/" + den);
            sc.close();
            return;
        }

        for (long i = 1; i <= max_iter; i++) {
            double val = ratio * i;
            long a_floor = (long) Math.floor(val);
            long a_ceil = (long) Math.ceil(val);

            double diff_floor = Math.abs(ratio - (double) a_floor / i);
            if (diff_floor < min_difference - epsilon) {
                min_difference = diff_floor;
                numerator = a_floor;
                denominator = i;
            }

            double diff_ceil = Math.abs((double) a_ceil / i - ratio);
            if (diff_ceil < min_difference - epsilon) {
                min_difference = diff_ceil;
                numerator = a_ceil;
                denominator = i;
            }
        }

        System.out.println(numerator + "/" + denominator);
        sc.close();
    }
}
